#### Phase 1: Identity and Access Management (Weeks 1-4)

**Step 1.1: Implement Tenant-Aware Authentication**

```csharp
public class TenantAuthenticationService
{
    private readonly IIdentityProvider _identityProvider;
    private readonly ITenantContextManager _tenantContext;
    private readonly IAuditLogger _auditLogger;
    private readonly IMfaService _mfaService;

    public async Task<AuthenticationResult> AuthenticateAsync(
        string username, string password, string tenantId)
    {
        // Validate tenant exists and is active
        var tenant = await ValidateTenantAsync(tenantId);

        // Authenticate with identity provider
        var authResult = await _identityProvider.AuthenticateAsync(
            username, password, tenant.IdentityProviderId);

        if (!authResult.Success)
        {
            await _auditLogger.LogFailedLoginAsync(username, tenantId);
            return AuthenticationResult.Failed("Authentication failed");
        }

        // Require MFA for PHI access
        if (tenant.RequiresMfa || authResult.User.AccessesPhi)
        {
            var mfaResult = await _mfaService.ValidateMfaAsync(
                authResult.User.Id, authResult.MfaToken);

            if (!mfaResult.Success)
            {
                await _auditLogger.LogFailedMfaAsync(username, tenantId);
                return AuthenticationResult.Failed("MFA validation failed");
            }
        }

        // Establish tenant context
        var tenantContext = new TenantContext
        {
            TenantId = tenantId,
            UserId = authResult.User.Id,
            Roles = authResult.User.Roles,
            SessionId = Guid.NewGuid().ToString()
        };

        await _auditLogger.LogSuccessfulLoginAsync(tenantContext);

        return AuthenticationResult.Success(
            GenerateJwtToken(tenantContext), tenantContext);
    }
}
```

**Step 1.2: Implement Role-Based Access Control**

```csharp
public class TenantAuthorizationService
{
    private readonly ITenantContextManager _tenantContext;
    private readonly IRolePermissionStore _permissionStore;
    private readonly IAuditLogger _auditLogger;

    public async Task<bool> AuthorizeAsync(
        string resource, string action)
    {
        // Get current tenant context
        var context = _tenantContext.GetCurrentTenant();
        if (context == null)
        {
            await _auditLogger.LogAuthorizationFailureAsync(
                "No tenant context", resource, action);
            return false;
        }

        // Validate resource belongs to current tenant
        if (!await ValidateResourceTenancyAsync(resource, context.TenantId))
        {
            await _auditLogger.LogCrossTenantAccessAttemptAsync(
                context, resource, action);
            return false;
        }

        // Check role permissions
        var permissions = await _permissionStore.GetPermissionsAsync(
            context.TenantId, context.Roles);

        var authorized = permissions.Any(p =>
            p.Resource == resource && p.Action == action);

        if (!authorized)
        {
            await _auditLogger.LogAuthorizationFailureAsync(
                context, resource, action);
        }

        return authorized;
    }
}
```

