#### Phase 2: Encryption and Key Management (Weeks 5-8)

**Step 2.1: Implement Tenant Key Management**

```csharp
public class TenantKeyManagementService
{
    private readonly IKeyVaultClient _keyVault;
    private readonly ITenantRegistry _tenantRegistry;
    private readonly IAuditLogger _auditLogger;

    public async Task<TenantEncryptionKeys> ProvisionTenantKeysAsync(
        string tenantId)
    {
        // Generate master encryption key for tenant
        var masterKey = await _keyVault.CreateKeyAsync(
            $"tenant-{tenantId}-master",
            KeyType.RSA,
            keySize: 4096);

        // Generate data encryption key (DEK) for PHI
        var dataKey = await _keyVault.CreateKeyAsync(
            $"tenant-{tenantId}-data",
            KeyType.AES,
            keySize: 256);

        // Set key rotation schedule (90 days)
        await _keyVault.SetKeyRotationPolicyAsync(
            dataKey.Id, rotationDays: 90);

        // Store key metadata with tenant
        await _tenantRegistry.UpdateTenantKeysAsync(tenantId, new TenantKeys
        {
            MasterKeyId = masterKey.Id,
            DataKeyId = dataKey.Id,
            CreatedDate = DateTime.UtcNow,
            NextRotationDate = DateTime.UtcNow.AddDays(90)
        });

        await _auditLogger.LogKeyProvisioningAsync(tenantId, masterKey.Id);

        return new TenantEncryptionKeys
        {
            MasterKeyId = masterKey.Id,
            DataKeyId = dataKey.Id
        };
    }

    public async Task<string> EncryptPhiAsync(
        string plaintext, string tenantId)
    {
        // Get tenant-specific data encryption key
        var tenantKeys = await _tenantRegistry.GetTenantKeysAsync(tenantId);

        // Encrypt using tenant DEK
        var ciphertext = await _keyVault.EncryptAsync(
            tenantKeys.DataKeyId, plaintext);

        await _auditLogger.LogEncryptionOperationAsync(
            tenantId, tenantKeys.DataKeyId);

        return ciphertext;
    }
}
```

**Step 2.2: Implement Automatic Key Rotation**

```csharp
public class KeyRotationService
{
    private readonly IKeyVaultClient _keyVault;
    private readonly ITenantRegistry _tenantRegistry;
    private readonly IDataReEncryptionService _reEncryption;
    private readonly IAuditLogger _auditLogger;

    public async Task RotateTenantKeysAsync(string tenantId)
    {
        var tenantKeys = await _tenantRegistry.GetTenantKeysAsync(tenantId);

        // Create new key version
        var newKey = await _keyVault.CreateKeyVersionAsync(
            tenantKeys.DataKeyId);

        // Re-encrypt all PHI data with new key (async background process)
        await _reEncryption.ScheduleReEncryptionAsync(
            tenantId, tenantKeys.DataKeyId, newKey.Id);

        // Update tenant key metadata
        await _tenantRegistry.UpdateTenantKeysAsync(tenantId, new TenantKeys
        {
            DataKeyId = newKey.Id,
            PreviousKeyId = tenantKeys.DataKeyId,
            NextRotationDate = DateTime.UtcNow.AddDays(90)
        });

        await _auditLogger.LogKeyRotationAsync(
            tenantId, tenantKeys.DataKeyId, newKey.Id);
    }
}
```

