#### Phase 3: Comprehensive Audit Logging (Weeks 9-12)

**Step 3.1: Implement PHI Access Audit Logger**

```csharp
public class PhiAuditLogger : IAuditLogger
{
    private readonly IAuditLogStore _auditStore;
    private readonly ITenantContextManager _tenantContext;
    private readonly ISiemIntegration _siem;

    public async Task LogPhiAccessAsync(
        string action,
        PhiRecord phiRecord,
        AccessOutcome outcome)
    {
        var context = _tenantContext.GetCurrentTenant();

        var auditEvent = new PhiAuditEvent
        {
            EventId = Guid.NewGuid(),
            Timestamp = DateTime.UtcNow,
            TenantId = context.TenantId,
            UserId = context.UserId,
            UserName = context.UserName,
            Action = action,
            ResourceType = "PHI",
            ResourceId = phiRecord.Id,
            PatientId = phiRecord.PatientId,
            Outcome = outcome,
            IpAddress = context.IpAddress,
            UserAgent = context.UserAgent,
            SessionId = context.SessionId
        };

        // Store in tamper-proof audit log
        await _auditStore.WriteAuditEventAsync(auditEvent);

        // Send to SIEM for real-time monitoring
        await _siem.SendEventAsync(auditEvent);

        // Alert on suspicious activity
        if (outcome == AccessOutcome.Denied ||
            IsSuspiciousActivity(auditEvent))
        {
            await _siem.RaiseSecurityAlertAsync(auditEvent);
        }
    }

    private bool IsSuspiciousActivity(PhiAuditEvent auditEvent)
    {
        // Detect unusual patterns: off-hours access, bulk downloads, etc.
        return auditEvent.Timestamp.Hour < 6 ||
               auditEvent.Timestamp.Hour > 20 ||
               auditEvent.Action == "BulkExport";
    }
}
```

**Step 3.2: Implement Audit Log Query Service**

```csharp
public class AuditLogQueryService
{
    private readonly IAuditLogStore _auditStore;
    private readonly IAuthorizationService _authorization;

    public async Task<IEnumerable<PhiAuditEvent>> QueryAuditLogsAsync(
        AuditLogQuery query)
    {
        // Validate user has audit access permission
        if (!await _authorization.AuthorizeAsync("AuditLogs", "Read"))
            throw new UnauthorizedAccessException();

        // Restrict query to current tenant only
        var context = _tenantContext.GetCurrentTenant();
        query.TenantId = context.TenantId;

        // Execute query with tenant filter
        var events = await _auditStore.QueryAsync(query);

        // Log the audit query itself (audit of audits)
        await LogAuditQueryAsync(context, query);

        return events;
    }
}
```

