#### Phase 5: Incident Response and Breach Management (Weeks 17-20)

**Step 5.1: Implement Incident Detection and Assessment**

```csharp
public class SecurityIncidentService
{
    private readonly IAuditLogStore _auditStore;
    private readonly INotificationService _notifications;
    private readonly IIncidentStore _incidentStore;

    public async Task<SecurityIncident> AssessSecurityIncidentAsync(
        SecurityAlert alert)
    {
        var incident = new SecurityIncident
        {
            IncidentId = Guid.NewGuid(),
            AlertId = alert.AlertId,
            DetectedAt = DateTime.UtcNow,
            IncidentType = alert.AlertType,
            Severity = DetermineSeverity(alert)
        };

        // Query audit logs for incident scope
        var relevantEvents = await _auditStore.QueryAsync(
            new AuditLogQuery
            {
                StartTime = alert.DetectedAt.AddHours(-24),
                EndTime = DateTime.UtcNow,
                UserId = alert.UserId,
                TenantId = alert.TenantId
            });

        // Determine affected tenants
        incident.AffectedTenants = relevantEvents
            .Select(e => e.TenantId)
            .Distinct()
            .ToList();

        // Assess PHI exposure
        var phiEvents = relevantEvents
            .Where(e => e.ResourceType == "PHI");

        incident.PhiRecordsAccessed = phiEvents
            .Select(e => e.ResourceId)
            .Distinct()
            .Count();

        incident.AffectedIndividuals = await CountAffectedIndividualsAsync(
            phiEvents);

        // Evaluate HIPAA breach threshold (500+ individuals)
        incident.RequiresBreachNotification =
            incident.AffectedIndividuals >= 500;

        // Store incident for tracking
        await _incidentStore.CreateIncidentAsync(incident);

        // Notify security team
        await _notifications.NotifySecurityTeamAsync(incident);

        return incident;
    }

    private async Task<int> CountAffectedIndividualsAsync(
        IEnumerable<PhiAuditEvent> phiEvents)
    {
        var patientIds = phiEvents
            .Select(e => e.PatientId)
            .Distinct();

        return patientIds.Count();
    }
}
```

**Step 5.2: Implement Breach Notification Workflow**

```csharp
public class BreachNotificationService
{
    private readonly IIncidentStore _incidentStore;
    private readonly ITenantRegistry _tenantRegistry;
    private readonly IEmailService _emailService;
    private readonly IDocumentGenerator _documentGenerator;

    public async Task ExecuteBreachNotificationAsync(
        Guid incidentId)
    {
        var incident = await _incidentStore.GetIncidentAsync(incidentId);

        if (!incident.RequiresBreachNotification)
            return;

        // Generate breach notification documents
        var notificationDoc = await _documentGenerator.GenerateBreachNotificationAsync(
            incident, BreachNotificationTemplate.Individual);

        // Notify affected tenants
        foreach (var tenantId in incident.AffectedTenants)
        {
            var tenant = await _tenantRegistry.GetTenantAsync(tenantId);

            await _emailService.SendAsync(
                to: tenant.SecurityContactEmail,
                subject: "Security Incident Notification - Action Required",
                body: notificationDoc,
                priority: EmailPriority.Urgent);

            // Log notification sent
            await _incidentStore.LogNotificationSentAsync(
                incidentId, tenantId, DateTime.UtcNow);
        }

        // Notify HHS OCR if breach affects 500+ individuals
        if (incident.AffectedIndividuals >= 500)
        {
            await NotifyHhsOcrAsync(incident);
        }

        // Update incident status
        incident.Status = IncidentStatus.NotificationsSent;
        incident.NotificationDate = DateTime.UtcNow;
        await _incidentStore.UpdateIncidentAsync(incident);
    }
}
```

